import { useNavigate } from '@tanstack/react-router'

export function CreatePostForm() {
  const navigate = useNavigate({ from: '/posts/new' })

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const response = await fetch('/api/posts', {
      method: 'POST',
      body: new FormData(event.currentTarget),
    })
    if (!response.ok) return
    const { id } = await response.json()
    await navigate({ to: '/posts/$postId', params: { postId: id } })
  }

  return <form onSubmit={handleSubmit}><button>Create</button></form>
}

import { createRootRouteWithContext, Outlet } from '@tanstack/react-router'
import { getRequest } from '@tanstack/start/server'
import { useRouteContext } from '@tanstack/react-router'

type RouterContext = { user: { email: string } | null }

const loadUser = async () => {
  const request = getRequest()
  return request.headers.get('x-user-email')
    ? { email: request.headers.get('x-user-email')! }
    : null
}

export const Route = createRootRouteWithContext<RouterContext>()({
  beforeLoad: async () => ({ user: await loadUser() }),
  component: () => <Outlet />,
})

export function UserStatus() {
  const { user } = useRouteContext({ from: '/' })
  return <span>{user?.email ?? 'Signed out'}</span>
}

